import Foundation
@testable import DockGroupsCore

/// A groups file with launch options, as this version writes it: delays on an app, a folder and a
/// file, and the apps chosen to open the folder, a website and the file. Generated by building this
/// version's DockGroupsCore and saving `group` with it; version 0.7.0 (`b32f6af`) reads the same
/// file with every item of the same kind, ignores the launch options and leaves them out when it
/// saves.
enum LaunchOptionsFixtures {
    static var group: DockGroup {
        var projects = GroupItem(fileURL: URL(fileURLWithPath: "/Users/me/Projects/cybokron", isDirectory: true), kind: .folder)
        projects.launch = ItemLaunchOptions(delay: 3, opener: ItemOpener(bundleIdentifier: "com.microsoft.VSCode", name: "Visual Studio Code"))
        var github = AppReference(websiteURL: URL(string: "https://github.com/cybokron")!, name: "Cybokron")
        github.launch = ItemLaunchOptions(opener: ItemOpener(bundleIdentifier: "com.google.Chrome", name: "Google Chrome"))
        var slack = AppReference(bundleIdentifier: "com.tinyspeck.slackmacgap", name: "Slack", path: "/Applications/Slack.app")
        slack.launch = ItemLaunchOptions(delay: 5)
        var report = GroupItem(fileURL: URL(fileURLWithPath: "/Users/me/Documents/Q3 Report.pdf"), kind: .file)
        report.details = ItemDetails(tags: ["finance"])
        report.launch = ItemLaunchOptions(delay: 10, opener: ItemOpener(bundleIdentifier: "com.apple.Preview", name: "Preview"))
        return DockGroup(
            id: UUID(uuidString: "0C0D1E00-0000-4000-8000-000000000080")!,
            name: "Coding",
            emoji: "💻",
            apps: [AppReference(bundleIdentifier: "com.apple.dt.Xcode", name: "Xcode"), projects, github, slack, report],
            freeLayoutSlots: [projects.normalizedBundleIdentifier: 2]
        )
    }

